const { body, session, documentHash } = $input.first().json;

const MODEL = 'gemini-2.5-flash';
const CACHE_TTL_SECONDS = 10800; // 3 hours

// Ad-hoc context (URL scrapes) is small and always sent inline, cached or not.
const adhocParts = [];
if (body.attachedContext && body.attachedContext.length > 0) {
  const ctxText = body.attachedContext
    .map(c => `### ${c.name}\n${c.content}`)
    .join('\n\n');
  adhocParts.push({ text: 'Reference material — treat this as the source of truth:\n\n' + ctxText });
}

// Cacheable context (attached KB docs + images) is the expensive, static part —
// this is what we try to cache server-side instead of retransmitting every turn.
const cacheableParts = [];
if (body.cachableContext && body.cachableContext.length > 0) {
  const ctxText = body.cachableContext
    .map(c => `### ${c.name}\n${c.content}`)
    .join('\n\n');
  cacheableParts.push({ text: 'Reference material — treat this as the source of truth:\n\n' + ctxText });
}
for (const img of (body.attachedImages || [])) {
  if (!img.data) continue;
  cacheableParts.push({ text: `Attached image: ${img.name}` });
  cacheableParts.push({ inline_data: { mime_type: img.mime || 'image/jpeg', data: img.data } });
}

let cacheName = null;
let cacheExpiresAt = null;
let usedCache = false;
let cacheError = null;

// Session store (loaded upstream in "Load Session") is the authority on cache
// validity — not the client — so a cache survives across devices/tabs, and an
// edited/swapped document invalidates it automatically via documentHash.
if (session && session.gemini && session.gemini.cacheId &&
    session.gemini.expiresAt && Date.now() < session.gemini.expiresAt &&
    session.gemini.documentHash === documentHash) {
  cacheName = session.gemini.cacheId;
  cacheExpiresAt = session.gemini.expiresAt;
  usedCache = true;
  console.log(`[Cache] Cache Hit: ${cacheName} — TTL Remaining: ${Math.max(0, Math.round((cacheExpiresAt - Date.now()) / 1000))}s`);
} else if (cacheableParts.length > 0) {
  if (session && session.gemini && session.gemini.cacheId) {
    console.log('[Cache] Cache Invalidated — document hash changed or cache expired');
  } else {
    console.log('[Cache] Cache Miss — no cached content on record');
  }
  // No valid cache on record, but there's reference material worth caching — create one.
  try {
    const geminiCred = await this.getCredentials('httpHeaderAuth'); // credential: "Gemini API Key"
    const cacheRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/cachedContents',
      headers: { [geminiCred.name]: geminiCred.value },
      body: {
        model: `models/${MODEL}`,
        systemInstruction: { parts: [{ text: body.systemPrompt }] },
        contents: [{ role: 'user', parts: cacheableParts }],
        ttl: `${CACHE_TTL_SECONDS}s`
      },
      json: true
    });
    if (cacheRes && cacheRes.name) {
      cacheName = cacheRes.name;
      cacheExpiresAt = Date.now() + CACHE_TTL_SECONDS * 1000;
      usedCache = true;
      console.log(`[Cache] Cache Created: ${cacheName} — TTL Remaining: ${CACHE_TTL_SECONDS}s`);
    }
  } catch (err) {
    // Reference material too small to cache, or the API rejected it — fall back to
    // sending it inline this turn, same as the old behaviour. Not fatal.
    cacheError = err.message || String(err);
    console.log(`[Cache] Redis/Gemini cache creation failed — falling back to inline context: ${cacheError}`);
  }
}

const contents = [];

if (adhocParts.length > 0) {
  contents.push({ role: 'user', parts: adhocParts });
  contents.push({ role: 'model', parts: [{ text: 'Got it — noted.' }] });
}

if (!usedCache && cacheableParts.length > 0) {
  contents.push({ role: 'user', parts: cacheableParts });
  contents.push({
    role: 'model',
    parts: [{ text: 'Got it, I have your reference material loaded. What do you need help with?' }]
  });
}

// Map conversation messages (role is already 'user'/'model' — Gemini-compatible)
for (const m of (body.messages || [])) {
  contents.push({ role: m.role, parts: [{ text: m.text }] });
}

const geminiBody = {
  contents,
  generationConfig: {
    temperature: 0.7,
    maxOutputTokens: 49152
  }
};

if (usedCache) {
  geminiBody.cachedContent = cacheName;
} else {
  geminiBody.system_instruction = { parts: [{ text: body.systemPrompt }] };
}

return [{
  json: {
    geminiBody,
    sessionId: body.chatId,
    documentHash,
    cacheName,
    cacheExpiresAt,
    usedCache,
    cacheError
  }
}];

